const body = $('Webhook').first().json.body;
const psiData = $('PageSpeed Insights API').first().json;
const htmlResponse = $('Fetch HTML').first().json;

// PSI Score (0-100)
const psiScore = psiData?.lighthouseResult?.categories?.performance?.score;
const speedScore = psiScore !== undefined ? Math.round(psiScore * 100) : null;

// SSL
const websiteUrl = body.website_url || '';
const hasSSL = websiteUrl.startsWith('https://');

// HTML analysis
const html = htmlResponse?.body || '';
const htmlLower = html.toLowerCase();

// Mobile friendly (viewport meta)
const isMobileFriendly = htmlLower.includes('name="viewport"') || htmlLower.includes("name='viewport'");

// Booking system detection
const bookingKeywords = ['reservar', 'book', 'appointment', 'cita', 'calendario', 'calendly', 'booksy', 'doctoralia', 'agenda online'];
const hasBooking = bookingKeywords.some(k => htmlLower.includes(k));

// Meta description
const metaMatch = html.match(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']+)["']/i)
               || html.match(/<meta[^>]+content=["']([^"']+)["'][^>]+name=["']description["']/i);
const metaDescription = metaMatch ? metaMatch[1].trim() : null;

// Meta title
const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i);
const metaTitle = titleMatch ? titleMatch[1].trim() : null;

return [{
  lead_id: body.lead_id,
  user_id: body.user_id || null,
  niche: body.niche,
  location: body.location,
  website_speed_score: speedScore,
  has_ssl: hasSSL,
  is_mobile_friendly: isMobileFriendly,
  has_booking_system: hasBooking,
  meta_title: metaTitle,
  meta_description: metaDescription,
  has_website: true
}];

const body = $('Webhook').first().json.body;
// No website — set all fields to null/false
return [{
  lead_id: body.lead_id,
  user_id: body.user_id || null,
  niche: body.niche,
  location: body.location,
  website_speed_score: null,
  has_ssl: null,
  is_mobile_friendly: null,
  has_booking_system: false,
  meta_title: null,
  meta_description: null,
  has_website: false
}];

// Opportunity Score
const d = $input.first().json;

let score = 0;
const painPoints = [];

if (!d.has_website) {
  score += 35;
  painPoints.push('no_website');
} else {
  if (d.website_speed_score !== null) {
    if (d.website_speed_score < 50) { score += 20; painPoints.push('slow_website'); }
    else if (d.website_speed_score <= 70) { score += 10; painPoints.push('slow_website'); }
  }
  if (!d.has_ssl) { score += 8; painPoints.push('no_ssl'); }
  if (!d.is_mobile_friendly) { score += 8; painPoints.push('not_mobile_friendly'); }
  if (!d.has_booking_system) { score += 10; painPoints.push('no_booking'); }
  if (!d.meta_description) { score += 5; painPoints.push('no_meta_description'); }
}

// Reviews and rating come from the lead in Supabase — handled after DB fetch
// For now calculate with what we have

const premiumNiches = ['dentista','abogado','médico','psicólogo','contador','inmobiliaria','notario','clínica'];
const nicheNorm = (d.niche || '').toLowerCase();
const isPremium = premiumNiches.some(n => nicheNorm.includes(n));
if (isPremium) score = Math.round(score * 1.2);

score = Math.min(score, 100);

return [{ ...d, opportunity_score: score, pain_points: JSON.stringify(painPoints) }];
